            'POST /kiosk/clock-questions' => ['tag' => $t, 'id' => 'createClockQuestion', 'summary' => 'Nowe pytanie / Nouvelle question', 'body' => 'ClockQuestionInput', 'response' => 'ClockQuestion', 'ok' => 201, 'errors' => [400, 422],
