            'POST /driver/run' => ['tag' => 'kiosk', 'id' => 'driverRun', 'summary' => 'Start / koniec trasy / Départ / fin de tournée', 'body' => 'DriverRunInput', 'response' => 'DriverRun', 'errors' => [400, 401, 403, 422]],
            'POST /driver/stops' => ['tag' => 'kiosk', 'id' => 'driverStop', 'summary' => 'Dostawa potwierdzona albo problem / Livraison confirmée ou problème', 'body' => 'DriverStopInput', 'response' => 'DriverStopResult', 'ok' => 201, 'errors' => [400, 401, 403, 422],
