            'GET /driver/report' => ['tag' => 'kiosk', 'id' => 'driverReport', 'summary' => 'Raport PDF trasy albo klienta / Rapport PDF de tournée ou d\'un client', 'response' => 'DocumentFile', 'errors' => [401, 403, 404, 422],
                'query' => ['date' => ['type' => 'string', 'format' => 'date'], 'vehicle_id' => ['type' => 'integer', 'description' => 'défaut : véhicule de la tablette'], 'customer_id' => ['type' => 'integer', 'description' => 'un seul client']],
