            'GET /driver/documents' => ['tag' => 'kiosk', 'id' => 'driverDocuments', 'summary' => 'Dokumenty dnia dla kierowców (PDF) / Documents du jour pour les chauffeurs (PDF)', 'response' => 'DocumentFile', 'errors' => [401, 403, 422],
