            'POST /kiosk/pair' => ['tag' => 'kiosk', 'id' => 'pairDevice', 'summary' => 'Sparuj tablet / Appairer la tablette', 'body' => 'PairInput', 'response' => 'DeviceToken', 'errors' => [400, 422],
