            'POST /kiosk/operations/{id:\d+}/start' => ['tag' => 'kiosk', 'id' => 'startOperation', 'summary' => 'Rozpocznij operację / Démarrer une opération', 'body' => 'StartInput', 'response' => 'KioskOperation', 'errors' => [401, 403, 404, 409],
