            'POST /kiosk/operations/{id:\d+}/pause' => ['tag' => 'kiosk', 'id' => 'pauseOperation', 'summary' => 'Pauza / Pause', 'response' => 'KioskOperation', 'errors' => [401, 403, 404, 409]],
