            'GET /kiosk/week' => ['tag' => 'kiosk', 'id' => 'kioskWeek', 'summary' => 'Plan tygodnia zespołu tabletu / Plan de la semaine de l\'équipe de la tablette', 'response' => 'TeamSheet', 'errors' => [401, 409, 422],
