            'GET /kiosk/deliveries/{id:\d+}' => ['tag' => 'kiosk', 'id' => 'kioskDelivery', 'summary' => 'Dostawa do przyjęcia (tablet) / Livraison à réceptionner (tablette)', 'response' => 'KioskDelivery', 'errors' => [401, 404],
