            'POST /kiosk/production/lines' => ['tag' => 'kiosk', 'id' => 'validateProductionLine', 'summary' => 'Zatwierdzenie linii dnia / Validation d\'une ligne du jour', 'body' => 'DayLineInput', 'response' => 'ProductionDay', 'errors' => [400, 401, 409, 422],
