            'POST /kiosk/photos' => ['tag' => 'kiosk', 'id' => 'uploadKioskPhoto', 'summary' => 'Zdjęcie straty / Photo d\'une perte', 'body' => 'PhotoInput', 'response' => 'PhotoUploaded', 'ok' => 201, 'errors' => [400, 401, 409, 422],
