            'GET /kiosk/stock' => ['tag' => 'kiosk', 'id' => 'kioskStock', 'summary' => 'Magazyn grupy / Stock du groupe', 'response' => 'KioskStock', 'errors' => [401, 409],
                'description' => "Produits du groupe de la tablette : stock (libre + palettes), commandé, min. / max. en cartons — même formule que Stan magazynu de l'ERP — et allowed_cartons = commandes au-delà du stock + jusqu'au stock max. (MTS ; sans max. : jusqu'au min.) − bon fait aujourd'hui sur la tablette. Produits sous le minimum d'abord. Liste de production de la semaine : GET /kiosk/week."],
            'GET /kiosk/recipes' => ['tag' => 'kiosk', 'id' => 'kioskRecipes', 'summary' => 'Receptury grupy tabletu / Recettes du groupe de la tablette', 'response' => 'KioskRecipeList', 'errors' => [401, 409],
                'query' => ['date' => ['type' => 'string', 'format' => 'date', 'description' => 'défaut : aujourd\'hui (quantité prévue du jour)']]],
            'GET /kiosk/recipes/{id:\d+}' => ['tag' => 'kiosk', 'id' => 'kioskRecipe', 'summary' => 'Receptura karty / Recette d\'une fiche', 'response' => 'KioskRecipe', 'errors' => [401, 404, 409],
                'query' => ['date' => ['type' => 'string', 'format' => 'date', 'description' => 'défaut : aujourd\'hui']],
                'description' => "Arbre de la recette (sous-recettes, matières, emballages, étapes de préparation) pour une unité de base : produit = 1 carton, semi-fini = 1 kg (sinon 1 recette) ; la tablette multiplie par la quantité choisie. routing = étapes de production de la fiche. media = photo du produit et 4 étapes en photos (fiche produit). producer = groupe qui prépare chaque sous-recette (other = un autre groupe que celui de la tablette). 409 ITEM_WITHOUT_RECIPE."],
            'GET /kiosk/recipes/components/{id:\d+}' => ['tag' => 'kiosk', 'id' => 'kioskComponentRecipe', 'summary' => 'Receptura półproduktu / kompozycji / Recette d\'un semi-fini ou d\'une composition', 'response' => 'KioskRecipe', 'errors' => [401, 404, 409],
                'description' => "Semi-fini ou composition sans fiche (par ex. préparé pour un autre groupe) : arbre pour 1 kg (rendement en g / ml) sinon 1 recette, groupe qui le prépare."],
            'GET /kiosk/machines' => ['tag' => 'kiosk', 'id' => 'kioskMachines', 'summary' => 'TRS maszyn grupy tabletu / TRS des machines du groupe de la tablette', 'response' => 'OeeDay', 'errors' => [401, 409],
                'query' => ['date' => ['type' => 'string', 'format' => 'date', 'description' => 'défaut : aujourd\'hui']],
                'description' => "Machines suivies (oee_tracked) du groupe de la tablette : état en cours, déroulé du jour, TRS = disponibilité × performance × qualité. Disponibilité = marche ÷ (marche + arrêts non planifiés ; pause et nettoyage = arrêts planifiés). Performance = temps standard des lots du jour sur la machine (gamme ; cobot = étape passée sur le cobot) ÷ temps de marche, au plus 100 %. Qualité = (produit − pertes) ÷ produit."],
            'POST /kiosk/machines/{id:\d+}/state' => ['tag' => 'kiosk', 'id' => 'kioskMachineState', 'summary' => 'Stan maszyny : praca, postój, koniec / État de la machine : marche, arrêt, fin', 'body' => 'MachineStateInput', 'response' => 'OeeDay', 'errors' => [400, 401, 403, 404, 409, 422],
                'description' => "Ferme l'état en cours et ouvre le nouveau (run, stop avec raison) ; off = fin de travail. Même état et même raison : rien ne change. 422 STOP_REASON_REQUIRED, STOP_NOTE_REQUIRED (raison other) ; 403 MACHINE_NOT_IN_YOUR_GROUP. client_uuid rejouable."],
            'GET /kiosk/development' => ['tag' => 'kiosk', 'id' => 'kioskDevelopment', 'summary' => 'Nowe produkty grupy tabletu / Produits à développer du groupe de la tablette', 'response' => 'DevProductList', 'errors' => [401, 409],
                'description' => "Produits en développement affichés sur la tablette (on_tablet) du groupe désigné (id_group) ; sans groupe désigné : sans section = tous les groupes, avec section = le groupe de cette section. Lancés et arrêtés : non. dev = étape (idée, test 1, test 2, recette à valider, lancement), prochaine action (trial / recipe / office), dernier résultat."],
            'GET /kiosk/development/summary' => ['tag' => 'kiosk', 'id' => 'kioskDevelopmentSummary', 'summary' => 'Nowe produkty na ekranie głównym / Nouveaux produits sur l\'accueil', 'response' => 'DevSummary', 'errors' => [401],
                'description' => "Sans personne identifiée (jeton de la tablette) : nom, étape et prochaine action des produits du groupe — widget de l'accueil. Tablette sans groupe : liste vide."],
            'GET /kiosk/development/{id:\d+}' => ['tag' => 'kiosk', 'id' => 'kioskDevelopmentProduct', 'summary' => 'Nowy produkt : etapy, testy, receptura, film, zdjęcia / Produit à développer : étapes, essais, recette, film, photos', 'response' => 'DevProduct', 'errors' => [401, 404, 409],
                'description' => "Étapes (flow : done / current / todo), essais (planifiés par le bureau avec consignes, faits sur la tablette avec photos en data URL), recette confirmée, notes, film (youtube / vimeo : lecteur intégré ; file : vidéo ; link : lien), photos de référence (data URL), journal, arbre de la recette ERP (null sans recette). 404 si le produit n'est pas affiché pour ce groupe."],
            'POST /kiosk/development/{id:\d+}/trials' => ['tag' => 'kiosk', 'id' => 'kioskDevelopmentTrial', 'summary' => 'Test zrobiony : zdjęcia, ilość, wynik / Essai fait : photos, quantité, résultat', 'body' => 'DevTrialInput', 'response' => 'DevProduct', 'ok' => 201, 'errors' => [400, 401, 404, 409, 422],
                'description' => "Confirmé une seule fois sur la tablette (personne identifiée) : termine le prochain essai planifié par le bureau, sinon ajoute l'essai suivant. 1 à 6 photos (JPEG redimensionné, heure de prise de vue), quantité, résultat ok / fix (à corriger) / ko ; notes obligatoires pour fix et ko. Étape : ok après l'essai 1 → test 2 ; ok après l'essai 2 et suivants → recette à valider ; fix → test 2. Notification dans l'ERP. 409 DEV_TRIAL_NOT_ALLOWED (lancement)."],
            'POST /kiosk/development/{id:\d+}/recipe' => ['tag' => 'kiosk', 'id' => 'kioskDevelopmentRecipe', 'summary' => 'Receptura zatwierdzona na tablecie / Recette validée sur la tablette', 'response' => 'DevProduct', 'errors' => [401, 404, 409],
                'description' => "Étape « recette à valider » → lancement ; produit test « en production » ; qui et quand. Le bureau relie ensuite le produit ERP (lancé). 409 DEV_RECIPE_NOT_READY (autre étape), DEV_RECIPE_MISSING (pas de recette ERP)."],
            'GET /kiosk/qr' => ['tag' => 'kiosk', 'id' => 'clockQr', 'summary' => 'Kod QR wejścia / wyjścia / QR code d\'entrée / sortie', 'response' => 'ClockQr', 'errors' => [401, 403, 422],
                'query' => ['base' => ['type' => 'string', 'example' => 'https://erp.example/production']],
                'description' => "QR changeant affiché par la tablette : {base}/kiosk/scan#t=<jeton> (kiosk.qr_ttl_s, renouvelé toutes les kiosk.qr_refresh_s). rows = matrice (1 = noir)."],

            'GET /kiosk/office/sections' => ['tag' => 'kiosk', 'id' => 'officeSections', 'summary' => 'Tablet biurowy : działy i osoby / Tablette de bureau : services et personnes', 'response' => 'OfficeSection', 'list' => true, 'errors' => [401, 403],
                'description' => "Tablette en mode « office » seulement (DEVICE_NOT_OFFICE, 403). Services (production_sections) avec leurs personnes actives, même sans profil de production (employee_id null, créé au premier QR) : PIN, téléphones enregistrés, entrée en cours (since), sortie du jour (left_at). id = production_employee.id."],
            'POST /kiosk/office/qr' => ['tag' => 'kiosk', 'id' => 'officeQr', 'summary' => 'Osobisty kod QR (osoba + dzień) / QR code personnel (personne + jour)', 'body' => 'OfficeQrInput', 'response' => 'OfficeQr', 'errors' => [400, 401, 403, 404, 422],
                'description' => "QR de la page {base}/kiosk/scan#t=<jeton> avec la tablette, la personne (emp) et le jour (day) ; valable kiosk.office_qr_ttl_s, renouvelé (refresh_s) avant. Seul le téléphone enregistré de cette personne le valide (sinon 403 QR_OTHER_PERSON), seulement ce jour-là (QR_EXPIRED) ; au premier scan, seule cette personne est proposée (PIN). since : heure du serveur, à repasser à GET /kiosk/office/status."],
            'GET /kiosk/office/status' => ['tag' => 'kiosk', 'id' => 'officeStatus', 'summary' => 'Czy wejście / wyjście zapisane? / Pointage enregistré ?', 'response' => 'OfficeStatus', 'errors' => [401, 403, 422],
                'query' => ['employee_id' => ['type' => 'integer'], 'since' => ['type' => 'string', 'example' => '2026-10-27 07:58:12']],
                'description' => "La tablette de bureau interroge pendant l'affichage du QR : dernier pointage (entrée ou sortie) de la personne depuis since, et si elle est présente."],

            'GET /kiosk/phone/people' => ['tag' => 'phone', 'id' => 'phonePeople', 'summary' => 'Osoby (pierwsze skanowanie) / Personnes (premier scan)', 'response' => 'PhonePerson', 'list' => true, 'errors' => [401]],
            'POST /kiosk/phone/enroll' => ['tag' => 'phone', 'id' => 'enrollPhone', 'summary' => 'Zarejestruj telefon: osoba + PIN / Enregistrer le téléphone : personne + PIN', 'body' => 'IdentifyInput', 'response' => 'PhoneToken', 'ok' => 201, 'errors' => [400, 401, 403, 409, 422, 423],
                'description' => "QR frais obligatoire (présence sur place). Jeton du téléphone (kiosk.phone_token_days) rendu une fois, seul son condensé est stocké. Mêmes blocages PIN que la tablette. QR personnel (tablette de bureau) : seulement la personne du QR (403 QR_OTHER_PERSON)."],
            'GET /kiosk/phone/me' => ['tag' => 'phone', 'id' => 'phoneMe', 'summary' => 'Stan wejścia / État du pointage', 'response' => 'ClockState', 'errors' => [401, 403],
                'description' => 'QR personnel (tablette de bureau) : refusé (403 QR_OTHER_PERSON) si le téléphone est enregistré au nom d\'une autre personne.'],
            'POST /kiosk/phone/clock' => ['tag' => 'phone', 'id' => 'phoneClock', 'summary' => 'Wejście / wyjście telefonem / Entrée / sortie au téléphone', 'body' => 'ClockInput', 'response' => 'ClockResult', 'errors' => [400, 401, 403, 409, 422],
                'description' => 'Comme POST /kiosk/clock ; la tablette du QR est enregistrée comme lieu du pointage. QR personnel : seulement le téléphone de la personne du QR.'],
            'POST /kiosk/phone/signatures' => ['tag' => 'phone', 'id' => 'phoneSign', 'summary' => 'Podpis palcem na telefonie / Signature au doigt sur le téléphone', 'body' => 'SignatureInput', 'response' => 'Signature', 'ok' => 201, 'errors' => [400, 401, 422]],
        ];
    }

    public static function schemas(): array
    {
        $int = ['type' => 'integer'];
        $nInt = ['type' => 'integer', 'nullable' => true];
        $num = ['type' => 'number'];
        $nNum = ['type' => 'number', 'nullable' => true];
        $str = ['type' => 'string'];
        $nStr = ['type' => 'string', 'nullable' => true];
        $bool = ['type' => 'boolean'];
        $dt = ['type' => 'string', 'example' => '2026-10-20 06:02:00'];
        return [
            'Device' => ['type' => 'object', 'properties' => ['id' => $int, 'name' => $str, 'group_id' => $nInt, 'mode' => ['type' => 'string', 'enum' => ['atelier', 'driver']], 'vehicle_id' => $nInt, 'vehicle_label' => $nStr,
                'active' => $bool, 'paired' => $bool, 'last_seen_at' => $nStr, 'pairing_pending' => $bool]],
            'KioskDelivery' => ['type' => 'object', 'properties' => ['id' => $int, 'code' => $str, 'status' => $str, 'supplier' => $nStr, 'delivery_date' => $nStr, 'receivable' => $bool,
                'lines' => ['type' => 'array', 'items' => ['type' => 'object', 'properties' => ['id' => $int, 'raw_material_id' => $int, 'name' => $str, 'base_unit' => $str, 'unit' => $str, 'factor' => $num,
                    'quantity' => $num, 'received_qty' => $num, 'remaining' => $num]]],
                'receipts' => ['type' => 'array', 'items' => ['type' => 'object', 'properties' => ['line_id' => $int, 'raw_material_id' => $int, 'received_on' => $str, 'quantity' => $num,
                    'lot_number' => $nStr, 'best_before' => $nStr, 'nc_id' => $nInt, 'employee' => $nStr]]]]],
            'DeviceInput' => ['type' => 'object', 'additionalProperties' => false, 'required' => ['name'], 'properties' => ['name' => ['type' => 'string', 'maxLength' => 100], 'group_id' => $nInt,
                'mode' => ['type' => 'string', 'enum' => ['atelier', 'driver'], 'description' => 'driver : tablette chauffeur (sans groupe)'], 'vehicle_id' => $nInt]],
            'DeviceUpdateInput' => ['type' => 'object', 'additionalProperties' => false, 'properties' => ['name' => ['type' => 'string', 'maxLength' => 100], 'group_id' => $nInt,
                'mode' => ['type' => 'string', 'enum' => ['atelier', 'driver']], 'vehicle_id' => $nInt, 'active' => $bool, 'new_pairing_code' => $bool]],
            'DriverVehicleChoice' => ['type' => 'object', 'properties' => ['id' => $int, 'label' => $str, 'carrier' => $nStr, 'driver' => $nStr]],
            'DriverRunInput' => ['type' => 'object', 'additionalProperties' => false, 'required' => ['date', 'vehicle_id', 'action'], 'properties' => ['date' => ['type' => 'string', 'format' => 'date'],
                'vehicle_id' => $int, 'action' => ['type' => 'string', 'enum' => ['start', 'finish']], 'driver_name' => ['type' => 'string', 'maxLength' => 100, 'nullable' => true]]],
            'DriverRun' => ['type' => 'object', 'properties' => ['driver_name' => $nStr, 'started_at' => $nStr, 'finished_at' => $nStr]],
            'DriverStopInput' => ['type' => 'object', 'additionalProperties' => false, 'required' => ['date', 'customer_id', 'status'], 'properties' => [
                'date' => ['type' => 'string', 'format' => 'date'], 'customer_id' => $int, 'vehicle_id' => $nInt, 'status' => ['type' => 'string', 'enum' => ['delivered', 'problem']],
                'reason' => ['type' => 'string', 'enum' => ['closed', 'refused', 'damaged', 'missing', 'late', 'other'], 'nullable' => true],
                'receiver_name' => ['type' => 'string', 'maxLength' => 100, 'nullable' => true], 'pallets_delivered' => $nInt, 'pallets_returned' => $nInt,
                'note' => ['type' => 'string', 'maxLength' => 500, 'nullable' => true], 'signature' => ['type' => 'string', 'description' => 'data:image/png;base64,…', 'nullable' => true],
                'photo' => ['type' => 'string', 'description' => 'data:image/jpeg;base64,… (driver.photo_max_kb)', 'nullable' => true], 'lat' => ['type' => 'number', 'nullable' => true], 'lng' => ['type' => 'number', 'nullable' => true],
                'recorded_at' => ['type' => 'string', 'example' => '2026-10-26 21:35:00', 'nullable' => true], 'driver_name' => ['type' => 'string', 'maxLength' => 100, 'nullable' => true],
                'client_uuid' => ['type' => 'string', 'maxLength' => 64, 'nullable' => true]]],
            'DriverStopResult' => ['type' => 'object', 'properties' => ['id' => $int, 'customer_id' => $int, 'status' => $str, 'recorded_at' => $str]],
            'DriverPhotoInput' => ['type' => 'object', 'additionalProperties' => false, 'required' => ['date', 'customer_id', 'kind', 'photo'], 'properties' => [
                'date' => ['type' => 'string', 'format' => 'date'], 'customer_id' => $int, 'vehicle_id' => $nInt, 'kind' => ['type' => 'string', 'enum' => ['before', 'after']],
                'photo' => ['type' => 'string', 'description' => 'data:image/jpeg;base64,… (driver.photo_max_kb)'], 'taken_at' => ['type' => 'string', 'example' => '2026-10-26 21:35:00', 'nullable' => true],
                'client_uuid' => ['type' => 'string', 'maxLength' => 64, 'nullable' => true], 'lat' => ['type' => 'number', 'nullable' => true], 'lng' => ['type' => 'number', 'nullable' => true],
                'driver_name' => ['type' => 'string', 'maxLength' => 100, 'nullable' => true]]],
            'DriverPhotoResult' => ['type' => 'object', 'properties' => ['id' => $int, 'stop_id' => $int, 'kind' => $str, 'taken_at' => $str, 'count' => $int]],
            'DriverDay' => ['type' => 'object', 'properties' => ['date' => $str, 'dates' => ['type' => 'array', 'items' => $str],
                'device' => ['type' => 'object', 'properties' => ['id' => $int, 'name' => $str, 'vehicle_id' => $nInt]],
                'vehicles' => ['type' => 'array', 'items' => ['type' => 'object', 'properties' => ['id' => $int, 'label' => $str, 'carrier' => $nStr, 'customers' => $int, 'pallets' => $int, 'departure' => $nStr]]],
                'vehicle' => ['type' => 'object', 'nullable' => true], 'run' => ['allOf' => [['$ref' => '#/components/schemas/DriverRun']], 'nullable' => true],
                'stops' => ['type' => 'array', 'items' => ['type' => 'object', 'properties' => ['n' => $int, 'customer_id' => $int, 'name' => $str, 'address' => $str, 'phone' => $nStr,
                    'pallets' => $int, 'cartons' => $num, 'weight_kg' => $num, 'scanned' => $int, 'documents' => ['type' => 'array', 'items' => ['type' => 'object', 'properties' => ['type' => $str, 'num' => $str]]],
                    'status' => ['type' => 'string', 'enum' => ['arrived', 'delivered', 'problem'], 'nullable' => true], 'recorded_at' => $nStr, 'arrived_at' => $nStr, 'receiver_name' => $nStr, 'reason' => $nStr,
                    'pallets_estimated' => $bool, 'pallet_numbers' => ['type' => 'array', 'items' => $int],
                    'photos' => ['type' => 'object', 'properties' => ['before' => ['type' => 'array', 'items' => ['type' => 'object']], 'after' => ['type' => 'array', 'items' => ['type' => 'object']]]],
                    'instructions' => ['type' => 'array', 'description' => 'consignes de livraison du client (procédure, alarme, clé, congélateur, contact), déchiffrées',
                        'items' => ['type' => 'object', 'properties' => ['key' => $str, 'label' => $str, 'value' => $str, 'secret' => $bool]]]]]],
                'counts' => ['type' => 'object', 'properties' => ['stops' => $int, 'delivered' => $int, 'problem' => $int, 'arrived' => $int]], 'max_photos' => $int,
                'reasons' => ['type' => 'array', 'items' => ['type' => 'object', 'properties' => ['code' => $str, 'label' => $str]]]]],
            'PairingCode' => ['type' => 'object', 'properties' => ['id' => $int, 'pairing_code' => ['type' => 'string', 'example' => 'K7M2Q9XA'], 'expires_at' => $dt]],
            'CredentialsInput' => ['type' => 'object', 'additionalProperties' => false, 'properties' => [
                'badge' => ['type' => 'string', 'maxLength' => 64, 'nullable' => true, 'description' => 'Numéro NFC / QR ; null = retirer'],
                'pin' => ['type' => 'string', 'pattern' => '^\d{4,6}$', 'nullable' => true], 'biometric_consent' => $bool, 'unlock' => $bool]],
            'Credentials' => ['type' => 'object', 'properties' => ['employee_id' => $int, 'has_badge' => $bool, 'has_pin' => $bool, 'biometric_consent' => $bool, 'locked' => $bool]],
            'PairInput' => ['type' => 'object', 'additionalProperties' => false, 'required' => ['code'], 'properties' => ['code' => $str]],
            'DeviceToken' => ['type' => 'object', 'properties' => ['device_token' => $str, 'device' => ['type' => 'object', 'properties' => ['id' => $int, 'name' => $str, 'group_id' => $nInt]]]],
            'KioskPerson' => ['type' => 'object', 'properties' => ['id' => $int, 'name' => $str, 'has_pin' => $bool, 'clocked_in' => $bool]],
            'IdentifyInput' => ['type' => 'object', 'additionalProperties' => false, 'required' => ['pin'], 'properties' => ['badge' => $str, 'employee_id' => $int, 'pin' => ['type' => 'string', 'pattern' => '^\d{4,6}$']]],
            'EmployeeToken' => ['type' => 'object', 'properties' => ['employee_token' => $str, 'expires_in' => $int, 'employee' => ['type' => 'object', 'properties' => ['id' => $int, 'name' => $str]]]],
            'Clock' => ['type' => 'object', 'properties' => ['id' => $int, 'clock_in' => $dt, 'clock_out' => $nStr, 'hours' => $num]],
            'ClockInput' => ['type' => 'object', 'additionalProperties' => false, 'properties' => ['direction' => ['type' => 'string', 'enum' => ['in', 'out']], 'client_uuid' => ['type' => 'string', 'format' => 'uuid'],
                'answers' => ['type' => 'array', 'description' => 'Questions du pointage (questions.in / questions.out) ; une question obligatoire sans yes: true → 422 CLOCK_QUESTIONS_REQUIRED',
                    'items' => ['type' => 'object', 'required' => ['question_id', 'yes'], 'properties' => ['question_id' => $int, 'yes' => $bool]]],
                'signature' => ['type' => 'string', 'description' => 'data:image/png;base64,… — signature au doigt dans l\'écran de validation (obligatoire selon kiosk.signature_on_clock_in / _out)']]],
            'ClockQuestion' => ['type' => 'object', 'properties' => ['id' => $int, 'text_pl' => $str, 'text_fr' => $nStr, 'direction' => ['type' => 'string', 'enum' => ['in', 'out', 'both']],
                'required' => $bool, 'active' => $bool, 'sort_order' => $int]],
            'ClockQuestionInput' => ['type' => 'object', 'additionalProperties' => false, 'required' => ['text_pl'], 'properties' => ['text_pl' => ['type' => 'string', 'maxLength' => 200],
                'text_fr' => ['type' => 'string', 'maxLength' => 200, 'nullable' => true], 'direction' => ['type' => 'string', 'enum' => ['in', 'out', 'both'], 'default' => 'in'],
                'required' => $bool, 'active' => $bool, 'sort_order' => $int]],
            'ClockQuestionUpdateInput' => ['type' => 'object', 'additionalProperties' => false, 'properties' => ['text_pl' => ['type' => 'string', 'maxLength' => 200],
                'text_fr' => ['type' => 'string', 'maxLength' => 200, 'nullable' => true], 'direction' => ['type' => 'string', 'enum' => ['in', 'out', 'both']],
                'required' => $bool, 'active' => $bool, 'sort_order' => $int]],
            'ClockQuestionDeleted' => ['type' => 'object', 'properties' => ['id' => $int, 'deleted' => $bool]],
            'ClockQuestions' => ['type' => 'object', 'description' => 'Questions actives à confirmer, dans la langue de l\'écran', 'properties' => [
                'in' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/ClockQuestionShort']], 'out' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/ClockQuestionShort']]]],
            'ClockQuestionShort' => ['type' => 'object', 'properties' => ['id' => $int, 'text' => $str, 'required' => $bool]],
            'ClockResult' => ['type' => 'object', 'properties' => ['replayed' => $bool, 'clock' => ['$ref' => '#/components/schemas/Clock'], 'signed' => $bool,
                'signature_required' => ['type' => 'boolean', 'description' => 'Toujours false : la signature se donne avec le pointage']]],
            'ClockCorrectionInput' => ['type' => 'object', 'additionalProperties' => false, 'required' => ['note'], 'properties' => ['clock_in' => $dt, 'clock_out' => ['type' => 'string', 'nullable' => true], 'note' => ['type' => 'string', 'maxLength' => 255]]],
            'ClockManualInput' => ['type' => 'object', 'additionalProperties' => false, 'required' => ['employee_id', 'clock_in', 'clock_out', 'note'], 'properties' => ['employee_id' => $int, 'clock_in' => $dt, 'clock_out' => $dt, 'note' => ['type' => 'string', 'maxLength' => 255]]],
            'KioskOperation' => ['allOf' => [['$ref' => '#/components/schemas/Operation'], ['type' => 'object', 'properties' => [
                'actual_start' => $nStr, 'actual_end' => $nStr, 'qty_good' => $nNum, 'qty_scrap' => $nNum, 'working' => ['type' => 'array', 'items' => $int], 'late' => $bool]]]],
            'KioskMe' => ['type' => 'object', 'properties' => ['employee' => ['type' => 'object', 'properties' => ['id' => $int, 'name' => $str]], 'clocked_in' => $bool,
                'clock' => ['allOf' => [['$ref' => '#/components/schemas/Clock']], 'nullable' => true], 'signature_on_clock_out' => $bool, 'signature' => ['type' => 'object', 'properties' => ['in' => $bool, 'out' => $bool], 'description' => 'Signature obligatoire à l\'entrée / à la sortie'], 'idle_logout_s' => $int,
                'operations' => ['type' => 'array', 'items' => ['$ref' => '#/components/schemas/KioskOperation']], 'working_on' => ['type' => 'array', 'items' => $int],
                'questions' => ['$ref' => '#/components/schemas/ClockQuestions']]],
            'StartInput' => ['type' => 'object', 'additionalProperties' => false, 'properties' => ['client_uuid' => ['type' => 'string', 'format' => 'uuid']]],
